%问题(3)方案1 
time=8; 
op=dataall(time).passenger;%选择8 点的乘客数据 
lp0=size(op,1); 
ebt=10;%每天补贴1 元 
lbt=30;%补贴30 天 
bt=ebt*ones(1,lbt); 
cbt=cumsum(bt);%累计补贴 
b0=1.645; 
baifenbi=@(butie)exp(b0-11.532./butie);%S curve 
cper=baifenbi(cbt)/100;%预测订单数 
t0=dataall(time-1).taxi; 
r=size(t0,1); 
matchn=[]; 
matchna=match(time).matchpstats;%8 点的难易度 
for i=1:lbt 
 p0=op; 
 p0(:,3)=p0(:,3).*(1-cper(i)); 
 disp=zeros(lp0,lc0); 
 for j=1:lp0

39 

 p00=ones(r,1)*p0(j,1:2); 
 d=dis(p00(:,1),p00(:,2),t0(:,1),t0(:,2)); 
 for k=1:lc0 
 ts=sum(t0(d<=C0(k),3)); 
 if ts<p0(j,3) 
 disp(j,k)=1; 
 elseif ts>p0(j,3) 
 disp(j,k)=-1; 
 else 
 disp(j,k)=0; 
 end 
 end 
 end 
 idx=ones(lp0,1)*(1:lc0); 
 idx(disp>0)=inf; 
 idxsel=min(idx,[],2); 
 idxsel(isinf(idxsel))=C0(end); 
 matchn(i).loc=p0(:,1:2); 
 matchn(i).matchp=disp; 
 matchn(i).matchpstats=idxsel; 
 matchna=[matchna,idxsel]; 
end 

